package com.justnpcx.starveil.core.kernel.ruleset

import java.io.File
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Assume.assumeTrue
import org.junit.Test

/**
 * The fixture is 94 bytes and was generated by the same algorithm sing-box
 * writes with: two exact names, one suffix and one keyword. It pins the parts
 * that are easy to get subtly wrong — the trie walk, the marker bytes and the
 * zlib envelope — without needing a network in CI.
 */
class SrsTest {

    private fun fixture(name: String): ByteArray =
        javaClass.getResourceAsStream("/$name")!!.readBytes()

    @Test
    fun `exact names, suffixes and keywords come back apart`() {
        val set = Srs.read(fixture("domain-small.srs"))

        assertEquals(3, set.version)
        assertEquals(1, set.rules.size)
        val rule = set.rules.single()
        assertEquals(listOf("ads.example.org", "exact.example.com"), rule.exactDomains)
        assertEquals(listOf("suffix.example.net"), rule.domainSuffixes)
        assertEquals(listOf("adserver"), rule.domainKeywords)
        assertFalse(rule.invert)
    }

    @Test
    fun `a corrupt file claiming a huge list is refused, not allocated`() {
        // "SRS", version 3, then zlib(1 rule, default type, keyword item with a
        // count of 500 million and nothing behind it). Allocating on that count
        // would be an OOM; the reader has to refuse it.
        val body = java.io.ByteArrayOutputStream().apply {
            write(1) // one rule
            write(0) // default rule
            write(3) // domain_keyword item
            var value = 500_000_000L
            while (true) {
                val byte = (value and 0x7F).toInt()
                value = value shr 7
                if (value != 0L) write(byte or 0x80) else { write(byte); break }
            }
        }.toByteArray()
        val deflated = java.io.ByteArrayOutputStream().apply {
            java.util.zip.DeflaterOutputStream(this).use { it.write(body) }
        }.toByteArray()
        val file = byteArrayOf(0x53, 0x52, 0x53, 3) + deflated

        val thrown = runCatching { Srs.read(file) }.exceptionOrNull()
        assertTrue("expected a format error, got " + thrown, thrown is SrsFormatException)
    }

    @Test
    fun `a truncated domain set fails as a format error, not a crash`() {
        // Cut the fixture in half: the zlib stream ends mid-matcher, which is
        // what a half-finished download looks like.
        val full = fixture("domain-small.srs")
        val cut = full.copyOf(full.size / 2)

        val thrown = runCatching { Srs.read(cut) }.exceptionOrNull()
        assertTrue("expected an IO failure, got " + thrown, thrown is java.io.IOException)
    }

    @Test
    fun `a file that is not a rule set is rejected by its header`() {
        val thrown = runCatching { Srs.read("not a rule set".toByteArray()) }
            .exceptionOrNull()
        assertTrue(thrown is SrsFormatException)
        assertTrue(thrown!!.message!!.contains("not a rule-set file"))
    }

    // ---- malformed input ------------------------------------------------
    //
    // Each of these is a file a truncated download or a corrupt CDN copy could
    // produce. None of them may allocate on an unverified number, spin, or
    // throw anything other than a format/IO error.

    private fun varint(value: Long): ByteArray {
        val out = java.io.ByteArrayOutputStream()
        var rest = value
        while (true) {
            val byte = (rest and 0x7F).toInt()
            rest = rest shr 7
            if (rest != 0L) out.write(byte or 0x80) else { out.write(byte); break }
        }
        return out.toByteArray()
    }

    /** "SRS" + version + zlib(body). */
    private fun envelope(body: ByteArray): ByteArray {
        val deflated = java.io.ByteArrayOutputStream().apply {
            java.util.zip.DeflaterOutputStream(this).use { it.write(body) }
        }.toByteArray()
        return byteArrayOf(0x53, 0x52, 0x53, 3) + deflated
    }

    private fun expectFormatError(bytes: ByteArray, why: String) {
        val thrown = runCatching { Srs.read(bytes) }.exceptionOrNull()
        assertTrue(why + " — got " + thrown, thrown is SrsFormatException)
    }

    @Test
    fun `an unknown rule type is refused`() {
        expectFormatError(envelope(byteArrayOf(1, 9)), "rule type 9")
    }

    @Test
    fun `an unknown rule item type is refused`() {
        expectFormatError(envelope(byteArrayOf(1, 0, 99.toByte())), "item type 99")
    }

    @Test
    fun `a string list that claims more entries than exist is refused`() {
        val body = byteArrayOf(1, 0, 3) + varint(500_000_000L)
        expectFormatError(envelope(body), "500 million keywords")
    }

    @Test
    fun `an IP set that claims more ranges than exist is refused`() {
        // version 1, then a uint64 count of 500 million, big-endian.
        val count = ByteArray(8).also { it[0] = 0x1D; it[1] = 0xCD.toByte(); it[2] = 0x65 }
        val body = byteArrayOf(1, 0, 6) + byteArrayOf(1) + count
        expectFormatError(envelope(body), "500 million IP ranges")
    }

    @Test
    fun `an IP address that is neither 4 nor 16 bytes is refused`() {
        val count = ByteArray(8).also { it[7] = 1 }
        val body = byteArrayOf(1, 0, 6) + byteArrayOf(1) + count + varint(5) + ByteArray(5)
        expectFormatError(envelope(body), "a 5-byte address")
    }

    @Test
    fun `a rule-set whose header version is in the future is refused`() {
        val deflated = java.io.ByteArrayOutputStream().apply {
            java.util.zip.DeflaterOutputStream(this).use { it.write(byteArrayOf(0)) }
        }.toByteArray()
        expectFormatError(byteArrayOf(0x53, 0x52, 0x53, 99) + deflated, "version 99")
    }

    /**
     * The real thing, when one is on disk: @@SRS_SAMPLE=/path/to/x.srs ./gradlew
     * :core:kernel:testDebugUnitTest --tests "*SrsTest*"@@. Skipped otherwise,
     * because CI has no business downloading a rule set to run a unit test.
     */
    @Test
    fun `a real rule set parses end to end`() {
        val path = System.getenv("SRS_SAMPLE")
        assumeTrue("SRS_SAMPLE is not set", path != null)
        val set = Srs.read(File(path!!).readBytes())

        val exact = set.exactDomains
        val suffixes = set.domainSuffixes
        val keywords = set.domainKeywords
        println(
            "SRS_SAMPLE: ${File(path).name} version=${set.version} rules=${set.rules.size} " +
                "exact=${exact.size} suffixes=${suffixes.size} keywords=${keywords.size}",
        )
        if (!File(path).name.contains("geoip")) {
            assertTrue("no exact names", exact.isNotEmpty())
            assertTrue("no suffixes", suffixes.isNotEmpty())
        }
        if (File(path).name.contains("geoip")) {
            val ranges = set.rules.flatMap { it.ipRanges }
            println("  ip ranges: ${ranges.size}")
            assertTrue("no IP ranges", ranges.isNotEmpty())
            fun v4(ip: String): Long {
                val parts = ip.split('.').map { it.toLong() }
                return (parts[0] shl 24) or (parts[1] shl 16) or (parts[2] shl 8) or parts[3]
            }
            fun inSet(ip: String) = ranges.any { it.contains(0L, v4(ip), false) }
            assertTrue("223.5.5.5 is not in the CN set", inSet("223.5.5.5"))
            assertTrue("8.8.8.8 is in the CN set", !inSet("8.8.8.8"))
        }
        if (File(path).name.contains("ads")) {
            assertTrue(
                "doubleclick.net is not in the ad set",
                exact.any { it == "doubleclick.net" } ||
                    suffixes.any { it == "doubleclick.net" || it == ".doubleclick.net" },
            )
        }
    }
}

